// Validate Approval Request — Panoptes M10

const body = $input.first().json.body ?? $input.first().json;

const incidentId = body.incident_id ?? null;
const decision =
  typeof body.decision === 'string'
    ? body.decision.toUpperCase()
    : null;

const operator = body.operator ?? 'unknown';

if (!incidentId) {
  throw new Error('Human approval request missing incident_id');
}

if (!['APPROVE', 'REJECT'].includes(decision)) {
  throw new Error(
    'Human approval decision must be APPROVE or REJECT'
  );
}

return [{
  json: {
    incident_id: String(incidentId),
    decision,
    operator: String(operator),
    decided_at: new Date().toISOString()
  }
}];

// Validate Pending Approval — Panoptes M10

const incident = $input.first().json;
const request = $('Validate Approval Request').first().json;

if (!incident.incident_id) {
  throw new Error('Panoptes approval incident not found');
}

if (incident.status !== 'WAITING_FOR_APPROVAL') {
  throw new Error(
    `Incident is not waiting for approval. Current status: ${incident.status}`
  );
}

if (incident.approval_status !== 'PENDING') {
  throw new Error(
    `Incident approval is not pending. Current approval_status: ${incident.approval_status}`
  );
}

if (!incident.proposed_action) {
  throw new Error(
    'Pending approval incident has no proposed_action'
  );
}

return [{
  json: {
    incident_id: incident.incident_id,

    decision: request.decision,
    operator: request.operator,
    decided_at: request.decided_at,

    proposed_action: incident.proposed_action,

    execution_id: incident.execution_id,
    retry_count: incident.retry_count,
    max_retries: incident.max_retries,

    current_status: incident.status,
    current_approval_status: incident.approval_status
  }
}];

// Build Approval Granted Update — Panoptes M10

const input = $input.first().json;

if (!input.incident_id) {
  throw new Error('Approved recovery missing incident_id');
}

if (input.decision !== 'APPROVE') {
  throw new Error('Approval branch received non-APPROVE decision');
}

if (input.proposed_action !== 'RETRY') {
  throw new Error(
    `Unsupported approved action: ${input.proposed_action}`
  );
}

return [{
  json: {
    incident_id: input.incident_id,

    execution_id: input.execution_id,
    retry_count: input.retry_count,
    max_retries: input.max_retries,

    status: 'RECOVERING',
    human_required: false,

    proposed_action: 'RETRY',
    approval_status: 'APPROVED',

    operator: input.operator,
    decided_at: input.decided_at,

    last_action: 'human_approval_granted',

    last_action_result: {
      success: true,
      decision: 'APPROVE',
      operator: input.operator,
      approved_action: 'RETRY'
    },

    updated_at: new Date().toISOString()
  }
}];

// Build APPROVAL_GRANTED Event — Panoptes M10

const update = $('Build Approval Granted Update').first().json;

return [{
  json: {
    event_id:
      `EVT-${update.incident_id.replace(/^INC-/, '')}-APPROVAL-GRANTED`,

    incident_id: update.incident_id,

    event_type: 'APPROVAL_GRANTED',

    event_message:
      `Human operator ${update.operator} approved recovery action ${update.proposed_action}.`,

    old_status: 'WAITING_FOR_APPROVAL',
    new_status: 'RECOVERING',

    tool_name: null,

    tool_result: {
      decision: 'APPROVE',
      operator: update.operator,
      approved_action: update.proposed_action,
      decided_at: update.decided_at
    }
  }
}];

const retry = $input.first().json;

if (!retry.incident_id) {
  throw new Error('Panoptes retry result missing incident_id');
}

if (!retry.retry_execution_id) {
  throw new Error('Panoptes retry did not return a retry_execution_id');
}

return [{
  json: {
    incident_id: retry.incident_id,

    status: 'VERIFYING',
    retry_count: retry.new_retry_count,

    proposed_action: 'RETRY',

    last_action: 'retry_execution',

    last_action_result: {
      success: retry.retry_result_received === true,
      original_execution_id: retry.original_execution_id,
      retry_execution_id: retry.retry_execution_id,
      previous_retry_count: retry.previous_retry_count,
      new_retry_count: retry.new_retry_count
    },

    updated_at: new Date().toISOString()
  }
}];

// Build RECOVERY_ATTEMPTED Event — Panoptes M8

const update = $('Build Recovery Attempt Update').first().json;

if (!update.incident_id) {
  throw new Error('Panoptes recovery event missing incident_id');
}

const result = update.last_action_result ?? {};

return [{
  json: {
    event_id: `EVT-${update.incident_id.replace(/^INC-/, '')}-RECOVERY-ATTEMPTED-${result.new_retry_count ?? 0}`,

    incident_id: update.incident_id,

    event_type: 'RECOVERY_ATTEMPTED',

    event_message: `Panoptes requested retry execution ${result.retry_execution_id ?? 'unknown'} for failed execution ${result.original_execution_id ?? 'unknown'}.`,

    old_status: 'RECOVERING',
    new_status: 'VERIFYING',

    tool_name: 'retry_execution',

    tool_result: {
      success: result.success ?? false,
      original_execution_id: result.original_execution_id ?? null,
      retry_execution_id: result.retry_execution_id ?? null,
      previous_retry_count: result.previous_retry_count ?? null,
      new_retry_count: result.new_retry_count ?? null
    }
  }
}];

// Build Approval Rejected Update — Panoptes M10

const input = $input.first().json;

if (!input.incident_id) {
  throw new Error('Rejected recovery missing incident_id');
}

if (input.decision !== 'REJECT') {
  throw new Error('Reject branch received non-REJECT decision');
}

return [{
  json: {
    incident_id: input.incident_id,

    status: 'ESCALATED',
    human_required: true,

    proposed_action: null,
    approval_status: 'REJECTED',

    operator: input.operator,
    decided_at: input.decided_at,

    last_action: 'human_approval_rejected',

    last_action_result: {
      success: true,
      decision: 'REJECT',
      operator: input.operator
    },

    updated_at: new Date().toISOString()
  }
}];

// Build APPROVAL_REJECTED Event — Panoptes M10

const update = $('Build Approval Rejected Update').first().json;

return [{
  json: {
    event_id:
      `EVT-${update.incident_id.replace(/^INC-/, '')}-APPROVAL-REJECTED`,

    incident_id: update.incident_id,

    event_type: 'APPROVAL_REJECTED',

    event_message:
      `Human operator ${update.operator} rejected the proposed recovery action.`,

    old_status: 'WAITING_FOR_APPROVAL',
    new_status: 'ESCALATED',

    tool_name: null,

    tool_result: {
      decision: 'REJECT',
      operator: update.operator,
      decided_at: update.decided_at
    }
  }
}];

// Build Recovered Update — Panoptes M9

const result = $input.first().json;

if (!result.incident_id) {
  throw new Error('Panoptes recovered update missing incident_id');
}

if (result.recovery_outcome !== 'RECOVERED') {
  throw new Error('Recovered branch received non-RECOVERED outcome');
}

const now = new Date().toISOString();

return [{
  json: {
    incident_id: result.incident_id,

    status: 'RECOVERED',
    human_required: false,

    proposed_action: null,
    approval_status: 'NOT_REQUIRED',

    retry_count: result.retry_count,

    last_action: 'verify_recovery',

    last_action_result: {
      success: true,
      recovery_outcome: result.recovery_outcome,
      retry_execution_id: result.retry_execution_id,
      retry_execution_status: result.retry_execution_status,
      reason: result.reason
    },

    updated_at: now,
    resolved_at: now
  }
}];

// Build INCIDENT_RECOVERED Event — Panoptes M9

const update = $('Build Recovered Update').first().json;

const result = update.last_action_result ?? {};

return [{
  json: {
    event_id:
      `EVT-${update.incident_id.replace(/^INC-/, '')}-RECOVERED-${update.retry_count}`,

    incident_id: update.incident_id,

    event_type: 'INCIDENT_RECOVERED',

    event_message:
      `Retry execution ${result.retry_execution_id ?? 'unknown'} completed successfully and the incident was recovered.`,

    old_status: 'VERIFYING',
    new_status: 'RECOVERED',

    tool_name: 'verify_recovery',

    tool_result: {
      success: true,
      retry_execution_id: result.retry_execution_id ?? null,
      retry_execution_status: result.retry_execution_status ?? null,
      recovery_outcome: result.recovery_outcome ?? 'RECOVERED'
    }
  }
}];

// Build Retry Failed Update — Panoptes M9
// v1.0.1 patch: preserve verification outcome state

const result = $input.first().json;

if (!result.incident_id) {
  throw new Error('Panoptes retry-failed update missing incident_id');
}

if (result.recovery_outcome !== 'RETRY_FAILED') {
  throw new Error('Retry-failed branch received unexpected recovery outcome');
}

const nextStatus = String(result.next_status ?? '').toUpperCase();

const allowedNextStatuses = [
  'RECOVERY_PENDING',
  'ESCALATED'
];

if (!allowedNextStatuses.includes(nextStatus)) {
  throw new Error(
    `Retry-failed branch received unexpected next_status: ${nextStatus || 'missing'}`
  );
}

const humanRequired = Boolean(result.human_required);

// An escalated retry failure must remain human-controlled.
if (nextStatus === 'ESCALATED' && !humanRequired) {
  throw new Error(
    'Escalated retry failure must require human attention'
  );
}

return [{
  json: {
    incident_id: result.incident_id,

    status: nextStatus,
    human_required: humanRequired,

    retry_count: result.retry_count,

    // RECOVERY_PENDING means another recovery attempt may be needed.
    // This does NOT mean another retry runs automatically.
    proposed_action:
      nextStatus === 'RECOVERY_PENDING' && !humanRequired
        ? 'RETRY'
        : null,

    approval_status: 'NOT_REQUIRED',

    last_action: 'verify_recovery',

    last_action_result: {
      success: false,
      recovery_outcome: result.recovery_outcome,
      retry_execution_id: result.retry_execution_id,
      retry_execution_status: result.retry_execution_status,
      next_status: nextStatus,
      loop_required: Boolean(result.loop_required),
      human_required: humanRequired,
      reason: result.reason,
      loop_termination_reason:
        result.loop_termination_reason ?? null
    },

    updated_at: new Date().toISOString()
  }
}];

// Build RETRY_FAILED Event — Panoptes M9
// v1.0.1 patch: reflect the actual persisted retry-failure state

const update = $('Build Retry Failed Update').first().json;
const result = update.last_action_result ?? {};

const status = String(update.status ?? '').toUpperCase();

if (
  status !== 'RECOVERY_PENDING' &&
  status !== 'ESCALATED'
) {
  throw new Error(
    `Retry-failed event received unexpected incident status: ${status || 'missing'}`
  );
}

const retryExecutionId =
  result.retry_execution_id ?? 'unknown';

const retryExecutionStatus =
  result.retry_execution_status ?? 'unknown';

const eventMessage =
  status === 'ESCALATED'
    ? `Retry execution ${retryExecutionId} ended with terminal status ${retryExecutionStatus}. Incident escalated for human attention.`
    : `Retry execution ${retryExecutionId} failed. Incident remains in recovery-pending state.`;

return [{
  json: {
    event_id:
      `EVT-${update.incident_id.replace(/^INC-/, '')}-RETRY-FAILED-${update.retry_count}`,

    incident_id: update.incident_id,

    event_type: 'RETRY_FAILED',
    event_message: eventMessage,

    old_status: 'VERIFYING',
    new_status: status,

    tool_name: 'verify_recovery',

    tool_result: {
      success: false,
      retry_execution_id:
        result.retry_execution_id ?? null,

      retry_execution_status:
        result.retry_execution_status ?? null,

      recovery_outcome:
        result.recovery_outcome ?? 'RETRY_FAILED',

      next_status: status,
      loop_required:
        Boolean(result.loop_required),

      human_required:
        Boolean(update.human_required)
    }
  }
}];

// Build Retry Exhausted Update — Panoptes M9

const result = $input.first().json;

if (!result.incident_id) {
  throw new Error('Panoptes retry-exhausted update missing incident_id');
}

if (result.recovery_outcome !== 'RETRY_EXHAUSTED') {
  throw new Error(
    'Retry-exhausted branch received unexpected recovery outcome'
  );
}

return [{
  json: {
    incident_id: result.incident_id,

    status: 'ESCALATED',
    human_required: true,

    retry_count: result.retry_count,

    proposed_action: null,
    approval_status: 'NOT_REQUIRED',

    last_action: 'verify_recovery',

    last_action_result: {
      success: false,
      recovery_outcome: result.recovery_outcome,
      retry_execution_id: result.retry_execution_id,
      retry_execution_status: result.retry_execution_status,
      retry_count: result.retry_count,
      max_retries: result.max_retries,
      reason: result.reason
    },

    updated_at: new Date().toISOString()
  }
}];

// Build RETRY_EXHAUSTED Event — Panoptes M9

const update = $('Build Retry Exhausted Update').first().json;
const result = update.last_action_result ?? {};

return [{
  json: {
    event_id:
      `EVT-${update.incident_id.replace(/^INC-/, '')}-RETRY-EXHAUSTED-${update.retry_count}`,

    incident_id: update.incident_id,

    event_type: 'RETRY_EXHAUSTED',

    event_message:
      `Retry execution ${result.retry_execution_id ?? 'unknown'} failed and the recovery attempt budget was exhausted.`,

    old_status: 'VERIFYING',
    new_status: 'ESCALATED',

    tool_name: 'verify_recovery',

    tool_result: {
      success: false,
      retry_execution_id: result.retry_execution_id ?? null,
      retry_execution_status: result.retry_execution_status ?? null,
      retry_count: result.retry_count ?? null,
      max_retries: result.max_retries ?? null,
      recovery_outcome:
        result.recovery_outcome ?? 'RETRY_EXHAUSTED'
    }
  }
}];

// Build Verification Pending Update — Panoptes M9
// v1.0.1 patch: preserve pending-verification human attention

const result = $input.first().json;

if (!result.incident_id) {
  throw new Error(
    'Panoptes verification-pending update missing incident_id'
  );
}

if (result.recovery_outcome !== 'PENDING') {
  throw new Error(
    'Pending branch received unexpected recovery outcome'
  );
}

const nextStatus = String(
  result.next_status ?? ''
).toUpperCase();

if (nextStatus !== 'VERIFYING') {
  throw new Error(
    `Pending verification received unexpected next_status: ${nextStatus || 'missing'}`
  );
}

const humanRequired =
  Boolean(result.human_required);

// Pending verification is intentionally paused for attention.
// Never silently clear this flag.
if (!humanRequired) {
  throw new Error(
    'Pending verification must require human attention'
  );
}

return [{
  json: {
    incident_id: result.incident_id,

    status: nextStatus,
    human_required: humanRequired,

    retry_count: result.retry_count,

    proposed_action: null,
    approval_status: 'NOT_REQUIRED',

    last_action: 'verification_pending',

    last_action_result: {
      success: null,
      recovery_outcome: result.recovery_outcome,
      retry_execution_id:
        result.retry_execution_id,
      retry_execution_status:
        result.retry_execution_status,

      next_status: nextStatus,
      loop_required:
        Boolean(result.loop_required),

      human_required: humanRequired,
      reason: result.reason,

      loop_termination_reason:
        result.loop_termination_reason ?? null
    },

    updated_at: new Date().toISOString()
  }
}];

// Build VERIFICATION_PENDING Event — Panoptes M9

const update = $('Build Verification Pending Update').first().json;
const result = update.last_action_result ?? {};

return [{
  json: {
    event_id:
      `EVT-${update.incident_id.replace(/^INC-/, '')}-VERIFICATION-PENDING-${update.retry_count}`,

    incident_id: update.incident_id,

    event_type: 'VERIFICATION_PENDING',

    event_message:
      `Retry execution ${result.retry_execution_id ?? 'unknown'} has not reached a terminal state yet.`,

    old_status: 'VERIFYING',
    new_status: 'VERIFYING',

    tool_name: 'verify_recovery',

    tool_result: {
      success: null,
      retry_execution_id: result.retry_execution_id ?? null,
      retry_execution_status: result.retry_execution_status ?? null,
      recovery_outcome:
        result.recovery_outcome ?? 'PENDING'
    }
  }
}];

// Build Retry Budget Exhausted Update — Panoptes M11.4

const result = $input.first().json;

if (!result.incident_id) {
  throw new Error('Retry budget result missing incident_id');
}

if (result.retry_budget_exhausted !== true) {
  throw new Error('Budget-exhausted branch received non-exhausted result');
}

return [{
  json: {
    incident_id: result.incident_id,

    status: 'ESCALATED',
    human_required: true,

    retry_count: result.new_retry_count,

    proposed_action: null,
    approval_status: 'APPROVED',

    last_action: 'retry_budget_exhausted',

    last_action_result: {
      success: false,
      retry_allowed: false,
      retry_budget_exhausted: true,
      original_execution_id: result.original_execution_id,
      retry_count: result.new_retry_count,
      reason: result.reason
    },

    updated_at: new Date().toISOString()
  }
}];

// Build RETRY_BUDGET_EXHAUSTED Event — Panoptes M11.4

const update = $('Build Retry Budget Exhausted Update').first().json;
const result = update.last_action_result ?? {};

return [{
  json: {
    event_id:
      `EVT-${update.incident_id.replace(/^INC-/, '')}-RETRY-BUDGET-EXHAUSTED-${update.retry_count}`,

    incident_id: update.incident_id,

    event_type: 'RETRY_BUDGET_EXHAUSTED',

    event_message:
      `Automatic recovery stopped because the retry budget was exhausted at ${update.retry_count} attempts.`,

    old_status: 'RECOVERING',
    new_status: 'ESCALATED',

    tool_name: 'retry_execution',

    tool_result: {
      success: false,
      retry_allowed: false,
      retry_budget_exhausted: true,
      original_execution_id: result.original_execution_id ?? null,
      retry_count: result.retry_count ?? update.retry_count,
      reason: result.reason ?? null
    }
  }
}];

// Build Retry Safety Blocked Update — Panoptes M11.5

const result = $input.first().json;

if (!result.incident_id) {
  throw new Error('Retry safety result missing incident_id');
}

if (result.retry_safety_blocked !== true) {
  throw new Error('Safety-blocked branch received non-blocked result');
}

return [{
  json: {
    incident_id: result.incident_id,

    status: 'ESCALATED',
    human_required: true,

    retry_count: result.new_retry_count,

    proposed_action: null,

    approval_status:
      result.approval_status === 'APPROVED'
        ? 'APPROVED'
        : 'NOT_REQUIRED',

    last_action: 'retry_safety_blocked',

    last_action_result: {
      success: false,
      retry_allowed: false,
      retry_safety_blocked: true,
      retry_safety: result.retry_safety,
      side_effect_risk: result.side_effect_risk,
      idempotency_guaranteed: result.idempotency_guaranteed,
      reason: result.reason
    },

    updated_at: new Date().toISOString()
  }
}];

// Build RETRY_SAFETY_BLOCKED Event — Panoptes M11.5

const update = $('Build Retry Safety Blocked Update').first().json;
const result = update.last_action_result ?? {};

return [{
  json: {
    event_id:
      `EVT-${update.incident_id.replace(/^INC-/, '')}-RETRY-SAFETY-BLOCKED-${update.retry_count}`,

    incident_id: update.incident_id,

    event_type: 'RETRY_SAFETY_BLOCKED',

    event_message:
      'Automatic recovery was blocked because the retry did not satisfy Panoptes safety requirements.',

    old_status: 'RECOVERING',
    new_status: 'ESCALATED',

    tool_name: 'retry_execution',

    tool_result: {
      success: false,
      retry_allowed: false,
      retry_safety_blocked: true,
      retry_safety: result.retry_safety ?? null,
      side_effect_risk: result.side_effect_risk ?? null,
      idempotency_guaranteed:
        result.idempotency_guaranteed ?? false,
      reason: result.reason ?? null
    }
  }
}];

// Build Approval API Response — REJECT

const incident = $('Get Incident').first().json;
const request = $('Validate Approval Request').first().json;

return [{
  json: {
    success: true,
    action: 'REJECT',
    incident_id: incident.incident_id,
    operator: request.operator,
    message: 'Recovery request rejected by operator.',
    previous_status: 'WAITING_FOR_APPROVAL'
  }
}];

// Build Approval API Response — APPROVE

const incident = $('Get Incident').first().json;
const request = $('Validate Approval Request').first().json;

return [{
  json: {
    success: true,
    action: 'APPROVE',
    incident_id: incident.incident_id,
    operator: request.operator,
    message: 'Approval accepted. Panoptes resumed recovery.',
    previous_status: 'WAITING_FOR_APPROVAL'
  }
}];
